@st.cache_data
def load_base_data_excel():

    xlsx_files = [
        f for f in os.listdir(".")
        if f.lower().endswith(".xlsx")
        and "馬場別基準タイム" in f
    ]

    if not xlsx_files:
        st.error("馬場別基準タイムのExcelが見つかりません")
        return None, None

    excel_filename = sorted(xlsx_files, key=lambda f: ("(2)" not in f, f))[0]

    try:
        xls = pd.ExcelFile(excel_filename)

        df_baba = (
            pd.read_excel(
                excel_filename,
                sheet_name="馬場別基準タイム"
            )
            if "馬場別基準タイム" in xls.sheet_names
            else None
        )

        df_f3 = (
            pd.read_excel(
                excel_filename,
                sheet_name="馬場別基準上がり3Fタイム"
            )
            if "馬場別基準上がり3Fタイム" in xls.sheet_names
            else None
        )

        return df_baba, df_f3

    except Exception as e:
        st.error(f"基準タイムExcelの読み込みに失敗しました: {e}")
        return None, None


df_base_master, df_f3_master = load_base_data_excel()
if df_f3_master is None:
    st.error("Excelの『馬場別基準上がり3Fタイム』シートが見つかりません。上がり3F評価は基準なしとして扱います。")


if df_base_master is not None and "距離" in df_base_master.columns:
    df_base_master["距離_num"] = pd.to_numeric(
        df_base_master["距離"]
        .astype(str)
        .str.extract(r"(\d+)")[0],
        errors="coerce",
    )


if df_f3_master is not None and "距離" in df_f3_master.columns:
    df_f3_master["距離_num"] = pd.to_numeric(
        df_f3_master["距離"]
        .astype(str)
        .str.extract(r"(\d+)")[0],
        errors="coerce",
    )


def geo_soha_excel_class(race_class):
    """走破タイムExcelの6クラスに正規化。重賞・LはOPを使う。"""
    import re
    c = str(race_class).strip().upper().replace("クラス", "").replace(" ", "")
    if c in ("G1", "G2", "G3", "GI", "GII", "GIII", "L", "OP", "オープン", "リステッド"):
        return "OP"
    if "新馬" in c: return "新馬"
    if "未勝利" in c: return "未勝利"
    m = re.search(r"([123])勝", c)
    if m: return m.group(1) + "勝"
    return None


def geo_soha_master_lookup(master, course, surface, distance, race_class, baba):
    """走破タイムExcelを競馬場・芝ダ・距離・6区分クラス・馬場で厳密検索。"""
    c = geo_soha_excel_class(race_class)
    b = str(baba).strip()
    surf = "ダート" if "ダ" in str(surface) else "芝"
    if master is None or master.empty or c is None or b not in ("良", "稍重", "重", "不良"):
        return None, c
    match = master.loc[
        master["競馬場"].astype(str).str.strip().eq(str(course).strip())
        & master["芝/ダート"].astype(str).str.strip().replace({"ダ":"ダート"}).eq(surf)
        & pd.to_numeric(master["距離_num"], errors="coerce").eq(float(distance))
        & master["クラス"].astype(str).str.strip().eq(c)
    ]
    if match.empty: return None, c
    value = pd.to_numeric(match.iloc[0][b], errors="coerce")
    if pd.isna(value) or float(value) <= 0: return None, c
    return float(value), c


def geo_f3_master_lookup(master, course, surface, distance, race_class, baba):
    """Excelの競馬場・芝ダ・距離・クラス・馬場に完全一致する上がり3F基準。"""
    if master is None or master.empty:
        return None
    course = str(course).strip()
    surface = "ダート" if "ダ" in str(surface) else "芝"
    race_class = str(race_class).strip().replace("クラス", "")
    # G1/G2/G3/LはOP区分にまとめる（Excelの分類に準拠）
    if race_class.upper() in ("G1", "G2", "G3", "GI", "GII", "GIII", "L", "OP", "オープン"):
        race_class = "OP"
    if race_class in ("1勝C", "2勝C", "3勝C"):
        race_class = race_class[:2]
    baba = str(baba).strip()
    if baba not in ("良", "稍重", "重", "不良"):
        return None
    matches = master.loc[
        master["競馬場"].astype(str).str.strip().eq(course)
        & master["芝/ダート"].astype(str).str.strip().eq(surface)
        & pd.to_numeric(master["距離_num"], errors="coerce").eq(float(distance))
        & master["クラス"].astype(str).str.strip().eq(race_class)
    ]
    if matches.empty:
        return None
    value = pd.to_numeric(matches.iloc[0][baba], errors="coerce")
    if pd.isna(value) or not (20.0 <= float(value) <= 60.0):
        return None
    return float(value)


# =========================================================
# JRA-VAN用変換
# =========================================================

def format_weight(value):
    if value is None:
        return np.nan

    try:
        return float(value) / 10.0
    except Exception:
        return np.nan


def format_odds(value):
    if value is None:
        return np.nan

    try:
        s = str(value).strip()

        if not s:
            return np.nan

        if s.isdigit():
            return int(s) / 10.0

        return float(s)

    except Exception:
        return np.nan


def style_from_value(value):
    mapping = {
        1: "逃げ",
        2: "先行",
        3: "差し",
        4: "追込",
    }

    try:
        ivalue = int(value)
        return mapping.get(ivalue, "差し")
    except Exception:
        text = str(value)

        if "逃" in text:
            return "逃げ"
        if "先" in text:
            return "先行"
        if "追" in text:
            return "追込"

        return "差し"


def condition_from_code(value):
    mapping = {
        1: "良",
        2: "稍重",
        3: "重",
        4: "不良",
    }

    try:
        return mapping.get(int(value), "不明")
    except Exception:
        text = str(value)

        for x in ["不良", "重", "稍重", "良"]:
            if x in text:
                return x

        return "不明"


def surface_from_race(race):
    surface_name = str(
        race.get(
            "surface",
            race.get(
                "surface_name",
                race.get("芝・ダ", "")
            )
        )
    ).strip()

    if "ダ" in surface_name:
        return "ダート"

    if "芝" in surface_name:
        return "芝"

    if "障" in surface_name:
        return "障害"

    track_code = str(
        race.get("track_code", "")
    )

    if track_code.startswith("2"):
        return "ダート"

    if track_code.startswith("1"):
        return "芝"

    if track_code.startswith("3"):
        return "障害"

    return "芝"


# =========================================================
# クラス判定
# =========================================================

def detect_class(race_name="", grade_code="", condition_code=""):
    race_name = str(race_name or "")
    grade_code = str(grade_code or "").strip().upper()
    condition_code = str(condition_code or "").strip()

    condition_map = {
        "701": "新馬",
        "703": "未勝利",
        "005": "1勝",
        "010": "2勝",
        "016": "3勝",
        "999": "OP",
    }

    grade_map = {
        "A": "G1",
        "B": "G2",
        "C": "G3",
    }

    if grade_code in grade_map:
        return grade_map[grade_code]

    if condition_code in condition_map:
        return condition_map[condition_code]
        
    if "G1" in race_name:
        return "G1"

    if "G2" in race_name:
        return "G2"

    if "G3" in race_name:
        return "G3"

    if "L" in race_name:
        return "L"

    if "新馬" in race_name:
        return "新馬"

    if "未勝利" in race_name:
        return "未勝利"

    if "1勝" in race_name:
        return "1勝"

    if "2勝" in race_name:
        return "2勝"

    if "3勝" in race_name:
        return "3勝"

    if "OP" in race_name:
        return "OP"

    return "OP"


